run:
$ErrorActionPreference = 'Stop'
$exe = $env:AUTARK_MNTWATCH_EXE
if (-not (Test-Path -LiteralPath $exe)) {
  Write-Error "MntWatch is missing at $exe. Run the app setup first."
  exit 1
}
$entries = @()
if ($env:AUTARK_MNTWATCH_FOLDERS) {
  $parsed = $env:AUTARK_MNTWATCH_FOLDERS | ConvertFrom-Json
  if ($parsed) { $entries = @($parsed) }
}
if ($entries.Count -eq 0) {
  Write-Host 'No folders are configured yet. Add at least one folder in the app settings.'
  exit 0
}
$installed = @()
try {
  $installed = @(wsl.exe -l -q | ForEach-Object { ($_ -replace "`0", '').Trim() } | Where-Object { $_ })
} catch {
  $installed = @()
}
$groups = @{}
foreach ($entry in $entries) {
  $folder = [string]$entry.path
  if (-not $folder) { continue }
  if (-not (Test-Path -LiteralPath $folder)) {
    Write-Host "Skipping missing folder: $folder"
    continue
  }
  $distros = @($entry.distros)
  if ($distros -contains 'all') { $distros = $installed }
  if ($distros.Count -eq 0) {
    Write-Host "Skipping folder without a selected distro: $folder"
    continue
  }
  foreach ($distro in $distros) {
    $name = [string]$distro
    if (-not $name) { continue }
    if (-not $groups.ContainsKey($name)) { $groups[$name] = New-Object System.Collections.ArrayList }
    if (-not $groups[$name].Contains($folder)) { [void]$groups[$name].Add($folder) }
  }
}
if ($groups.Count -eq 0) {
  Write-Host 'Nothing to bridge: no folder has a selected distro.'
  exit 0
}
$children = New-Object System.Collections.ArrayList
foreach ($name in @($groups.Keys)) {
  $folders = @($groups[$name])
  $arguments = @('--distro', ('"' + $name + '"'), '--run')
  foreach ($folder in $folders) { $arguments += ('"' + $folder + '"') }
  Write-Host "Bridging $($folders.Count) folder(s) into $name"
  $child = Start-Process -FilePath $exe -ArgumentList $arguments -NoNewWindow -PassThru
  [void]$children.Add($child)
}
foreach ($child in $children) { $child.WaitForExit() }
